final class METDutyRollMonthlyProcessingJob
{
    boolean             runForExcise;
    RecordInsertList    recordInsertList;
    TransDate           startDate;    
    private TransDate   effectiveDate;
    private boolean     cpi;
    private utcdatetime effectiveDateTime;


}

Method.Source:
/// <summary>
/// Main process method
/// </summary>
/// <param name = "_contract">_contract</param>
public void process(METDutyRollMonthlyContract _contract) 
{
    #OCCRetryCount

    MetDutyRollMonthlyTmp     dutyRollMonthlyTmp;
    container                   conItems;
    int                         i;

    try
    {
        ttsbegin;
        runForExcise        = _contract.parmRunForExcise();
        startDate           = _contract.parmStartDate();
        conItems            = _contract.parmConItems();
        effectiveDate       = _contract.parmEffectiveDate();
        effectiveDateTime   = DateTimeUtil::newDateTime(_contract.parmEffectiveDate(), 0);
        cpi                 = _contract.parmCpi();

        recordInsertList    = new RecordInsertList(tableNum(METDutyRollValuesLine));

        for (i=1; i <= conlen(conItems); i++)
        {                                
            dutyRollMonthlyTmp = conpeek(conItems, i);

            this.processItem(dutyRollMonthlyTmp.SiteId, dutyRollMonthlyTmp.ItemId);
        }

        recordInsertList.insertDatabase();
        ttscommit;
    }
    catch(Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

/// <summary>
/// process one item
/// </summary>
/// <param name = "_siteId">InventSiteId</param>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_refRecId">RefRecId</param>
private void processItem(InventSiteId  _siteId, ItemId  _itemId)
{
    METDutyRollValuesLine       dutyRollValuesLine;
    InventTable                 inventTable = InventTable::find(_itemId);
    METInventTable              metInventTable = METInventTable::find(_itemId);
    METTariffItemCode           tariffItemCode;
    METExciseSiteDutySetup      exciseSiteDutySetup;
    Qty                         lalqty;
    container                   con;

    dutyRollValuesLine.clear();
    dutyRollValuesLine.CalcDate     = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
    dutyRollValuesLine.ValidFrom    = DateTimeUtil::newDateTime(startDate, 0);
    dutyRollValuesLine.Site         = _siteId;
    dutyRollValuesLine.ItemId       = _itemId;
    dutyRollValuesLine.ItemName     = inventTable.NameAlias;
    dutyRollValuesLine.Unit         = inventTable.salesUnitId();
    dutyRollValuesLine.AverageVFD   = this.calcAvgDutyCase(_itemId, _siteId);
    tariffItemCode                  = METTariffItemCode::findRecId(metInventTable.METTariffItemCodeBaseRecid,effectiveDate);
    //Duty amount = (pack size * Bottlesize * (AlcStrn/100) * Duty-LAL) + (VFD * (Adval Rate/100))
    dutyRollValuesLine.TotalDutyPerCase = metInventTable.ItemPack * metInventTable.BottleSize * (metInventTable.AlcoholContent/100) * tariffItemCode.DutyLAL + (dutyRollValuesLine.AverageVFD * tariffItemCode.AdValoremOrBeerSubsidyRate/100);

    if(runForExcise || cpi)
    {
        exciseSiteDutySetup = METExciseSiteDutySetup::find(_siteId, _itemId, true);
        if (exciseSiteDutySetup.RecId)
        {
            // LAL = Alcohol Content (%) x Bottle Size (L) x Quantity (each)
            lalqty = (metInventTable.AlcoholContent / 100) * metInventTable.BottleSize * metInventTable.ItemPack;
            exciseSiteDutySetup.ExcisePerCase   = tariffItemCode.DutyLAL * lalqty;
            exciseSiteDutySetup.ValidFrom       = startDate;
            exciseSiteDutySetup.update();
        }

    }

    recordInsertList.add(dutyRollValuesLine);
}

/// <summary>
/// calculate average VFD and average inventory quantity
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_siteId">InventSiteId</param>
/// <returns>METValueForDuty</returns>
private METValueForDuty calcAvgDutyCase(ItemId _itemId, InventSiteId _siteId)
{
    METValueForDuty avgDuty;
    METExciseInformationTable   exciseInformationTable;
    METExciseRegisterEntry      exciseRegisterEntry;
    PurchLine                   purchLine;
    TransDateTime               startDateTime;
    TransDateTime               endDateTime;
    TransDateTime               currentDateTime;
    TransDate                   transDate;
    int                         countRecords;
    InventTransferLine          inventTransferLine;
    Amount                      dutyRateReceived = 0;
    METPOTODutyRecords          metPOTODutyRecords;
    RecordInsertList            recordInsertListTmp;

    recordInsertListtmp = new RecordInsertList(tableNum(METDutyRollMonthlyTmp), true, true, true, true, true, metPOTODutyRecords);

    transDate = effectiveDate;//DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
    endDateTime = DateTimeUtil::addSeconds(DateTimeUtil::newDateTime(transDate+1, 0), - 1);
    transDate = mkDate(1, mthOfYr(transDate), year(transDate));
    startDateTime = DateTimeUtil::newDateTime(transDate, 0);

    if (this.isCurrentOrFutureMonth(effectiveDate))
    {
        // future date
        while select firstonly10 DutyRateReceived from exciseRegisterEntry
        order by CreatedDateTime desc
        where  exciseRegisterEntry.ItemId == _itemId
            && exciseRegisterEntry.SiteId == _siteId
        exists join exciseInformationTable
        where  exciseInformationTable.InventTransType == InventTransType::Purch
            && exciseInformationTable.ItemId == _itemId
            && exciseInformationTable.SiteId == _siteId
            && exciseInformationTable.ReferenceNumber == exciseRegisterEntry.OrderNumber
        exists join purchLine
        where purchLine.InventTransId == exciseInformationTable.InventTransId
            && purchLine.CreatedDateTime >= startDateTime
            && purchLine.CreatedDateTime <= endDateTime
        {
            if (countRecords == METConstants::TenValue)
            {
                /// createddateteime + dutyvalue
                break;
            }
            metPOTODutyRecords.CreatedDateTimeVal = purchLine.CreatedDateTime;
            metPOTODutyRecords.DutyRateReceived = exciseRegisterEntry.DutyRateReceived;
            recordInsertList.add(metPOTODutyRecords);

            dutyRateReceived += exciseRegisterEntry.DutyRateReceived;
            countRecords++;
        }
        // check for Transfer order records 
        countRecords = 0;
        while select firstonly10 DutyRateReceived from exciseRegisterEntry
        order by CreatedDateTime desc
        where  exciseRegisterEntry.ItemId == _itemId
            && exciseRegisterEntry.SiteId == _siteId
        exists join exciseInformationTable
        where  exciseInformationTable.InventTransType == InventTransType::TransferOrderReceive
            && exciseInformationTable.ItemId == _itemId
            && exciseInformationTable.SiteId == _siteId
            && exciseInformationTable.ReferenceNumber == exciseRegisterEntry.OrderNumber
        exists join inventTransferLine
        where inventTransferLine.InventTransId == exciseInformationTable.InventTransId
            && inventTransferLine.CreatedDateTime >= startDateTime
            && inventTransferLine.CreatedDateTime <= endDateTime
        {
            if (countRecords == METConstants::TenValue)
            {
                /// createddateteime + dutyvalue
                break;
            }
            metPOTODutyRecords.CreatedDateTimeVal = inventTransferLine.CreatedDateTime;
            metPOTODutyRecords.DutyRateReceived = exciseRegisterEntry.DutyRateReceived;
            recordInsertList.add(metPOTODutyRecords);
            dutyRateReceived += exciseRegisterEntry.DutyRateReceived;
            countRecords++;
        }
        recordInsertList.insertDatabase();
        select firstonly10 sum (DutyRateReceived) from metPOTODutyRecords
            order by CreatedDateTimeVal desc;

        if (countRecords)
        {
            avgDuty = metPOTODutyRecords.DutyRateReceived / (countRecords);//dutyRateReceived
        }
    }
    else
    {
        // current month dort by modified date of PurchLine
        while select firstonly10 DutyRateReceived from exciseRegisterEntry
        order by purchLine.ModifiedDateTime desc
        where  exciseRegisterEntry.ItemId == _itemId
            && exciseRegisterEntry.SiteId == _siteId
        exists join exciseInformationTable
        where  exciseInformationTable.InventTransType == InventTransType::Purch
            && exciseInformationTable.ItemId == _itemId
            && exciseInformationTable.SiteId == _siteId
            && exciseInformationTable.ReferenceNumber == exciseRegisterEntry.OrderNumber
        exists join purchLine
        where purchLine.InventTransId == exciseInformationTable.InventTransId 
        {
            if (countRecords == METConstants::TenValue)
            {
                /// createddateteime + dutyvalue
                break;
            }
            metPOTODutyRecords.CreatedDateTimeVal = purchLine.CreatedDateTime;
            metPOTODutyRecords.DutyRateReceived = exciseRegisterEntry.DutyRateReceived;
            recordInsertList.add(metPOTODutyRecords);
            dutyRateReceived += exciseRegisterEntry.DutyRateReceived;
            countRecords++;
        }
        // check for Transfer order records
        countRecords = 0;
        while select firstonly10 DutyRateReceived from exciseRegisterEntry
        order by inventTransferLine.ModifiedDateTime desc
        where  exciseRegisterEntry.ItemId == _itemId
            && exciseRegisterEntry.SiteId == _siteId
        exists join exciseInformationTable
        where  exciseInformationTable.InventTransType == InventTransType::TransferOrderReceive
            && exciseInformationTable.ItemId == _itemId
            && exciseInformationTable.SiteId == _siteId
            && exciseInformationTable.ReferenceNumber == exciseRegisterEntry.OrderNumber
        exists join inventTransferLine
        where inventTransferLine.InventTransId == exciseInformationTable.InventTransId
            && inventTransferLine.CreatedDateTime >= startDateTime
            && inventTransferLine.CreatedDateTime <= endDateTime
        {
            if (countRecords == METConstants::TenValue)
            {
                /// createddateteime + dutyvalue
                break;
            }
            metPOTODutyRecords.CreatedDateTimeVal = inventTransferLine.CreatedDateTime;
            metPOTODutyRecords.DutyRateReceived = exciseRegisterEntry.DutyRateReceived;
            recordInsertList.add(metPOTODutyRecords);
            dutyRateReceived += exciseRegisterEntry.DutyRateReceived;
            countRecords++;
        }
        recordInsertList.insertDatabase();

        select firstonly10 sum (DutyRateReceived) from metPOTODutyRecords
            order by CreatedDateTimeVal desc;

        if (countRecords)
        {
            avgDuty = metPOTODutyRecords.DutyRateReceived / (countRecords);//dutyRateReceived
        }

    }
    return avgDuty;
}

/// <summary>
/// get current or future month
/// </summary>
/// <param name = "_inputDate">_inputDate</param>
/// <returns>boolean</returns>
public boolean isCurrentOrFutureMonth(Transdate _inputDate)
{
    date currentDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

    // Check if the date is in current month
    if (mthOfYr(_inputDate) == mthOfYr(currentDate) && year(_inputDate) == year(currentDate))
    {
        return true; // Current month
    }

    // Check if the date is in future month
    if ((year(_inputDate) > year(currentDate)) ||
    (year(_inputDate) == year(currentDate) && mthOfYr(_inputDate) > mthOfYr(currentDate)))
    {
        return true; // Future month
    }

    return false; // Past month
}
